export const routes={basic:{name:'Làm quen côn số',segments:[[350,0],[220,.04],[180,0],[220,-.04],[350,0]]},hill:{name:'Khởi hành ngang dốc',segments:[[250,.08],[180,0],[350,.12],[220,-.06],[300,0]]},descent:{name:'Kiểm soát xuống dốc',segments:[[220,-.08],[380,-.12],[180,0],[280,.06],[240,0]]}};
export class Car{
 constructor(route='basic'){this.route=route;this.x=0;this.v=0;this.rpm=850;this.gear=0;this.clutch=1;this.gas=0;this.brake=0;this.running=true;this.stallTime=0;this.time=0;this.errors=[];this.cooldown={};this.finished=false;this.stalls=0;this.maxSpeed=0;}
 get length(){return routes[this.route].segments.reduce((a,s)=>a+s[0],0)}
 get grade(){let p=Math.max(0,this.x);for(const [len,g] of routes[this.route].segments){if(p<len)return g;p-=len}return 0}
 fault(code,title,detail){if(this.time-(this.cooldown[code]??-100)<5)return;this.cooldown[code]=this.time;this.errors.unshift({code,title,detail,time:this.time});}
 shift(n){if(n===this.gear)return;if(this.clutch<.9){this.fault('clutch','Chưa đạp hết côn','Giữ A đến khi côn đạt 100%, rồi chọn số. Côn chưa ngắt khiến việc gài số bị từ chối.');return}if((n===-1&&this.v>.3)||(n>0&&this.v<-.3)){this.fault('reverse','Dừng xe trước khi đổi hướng','Đạp phanh cho xe dừng hẳn rồi mới chuyển giữa số tiến và số lùi.');return}const ratio=[0,3.6,2.1,1.4,1.05,.82][n]||3.4;if(n!==0&&Math.abs(this.v)*ratio*130>6500){this.fault('downshift','Số quá thấp cho tốc độ hiện tại','Giảm tốc bằng phanh trước khi về số. Gài số thấp lúc chạy nhanh có thể ép động cơ vượt vòng tua an toàn.');return}this.gear=n;}
 start(){if(this.clutch<.9&&this.gear!==0){this.fault('start','Đạp côn để khởi động','Giữ A hoặc về N trước khi bấm khởi động.');return}this.running=true;this.rpm=850;this.stallTime=0;}
 step(dt,input){if(this.finished)return;dt=Math.min(dt,.05);this.time+=dt;const approach=(v,t,r)=>v+Math.sign(t-v)*Math.min(Math.abs(t-v),r*dt);this.clutch=approach(this.clutch,input.clutch?1:0,input.clutch?3.5:.65);this.gas=approach(this.gas,input.gas?1:0,1.8);this.brake=approach(this.brake,input.brake?1:0,3);const ratio=this.gear===-1?3.4:[0,3.6,2.1,1.4,1.05,.82][this.gear];const engage=this.gear===0?0:Math.pow(1-this.clutch,1.5);const wheelRPM=Math.abs(this.v)*ratio*130;const freeRPM=850+this.gas*5700;const target=freeRPM*(1-engage)+wheelRPM*engage;this.rpm=this.running?approach(this.rpm,target,5500):approach(this.rpm,0,6000);
 const torque=this.running?(this.gas*190+45*Math.max(0,1-(this.rpm-850)/400))*Math.min(1,this.rpm/850):0;const drive=torque*ratio*4/.31/1250*engage*(this.gear===-1?-1:1);const engineBrake=(this.running?.32:.6)*ratio*engage*Math.sign(this.v)*(1-this.gas);const other=drive-9.81*this.grade-engineBrake-.0005*this.v*Math.abs(this.v);const resistance=this.brake*9+.12;let next=this.v+other*dt;if(Math.abs(next)<=resistance*dt)next=0;else next-=Math.sign(next)*resistance*dt;this.v=next;this.x+=this.v*dt;this.maxSpeed=Math.max(this.maxSpeed,Math.abs(this.v)*3.6);
 if(this.running&&this.gear!==0&&engage>.5&&this.rpm<550){this.stallTime+=dt;if(this.stallTime>.45){this.running=false;this.stalls++;this.fault('stall','Động cơ đã tắt máy','Côn bắt khi vòng tua quá thấp hoặc số quá cao. Đạp côn + phanh, khởi động lại, chọn số 1 và thêm ga khi nhả côn.')}}else this.stallTime=0;
 if(this.rpm>5800)this.fault('rpm','Vòng tua quá cao','Nhả bớt ga. Nếu xe đang chạy ở số tiến, đạp côn và lên số phù hợp để hạ vòng tua.');
 if(this.v<-.65&&this.gear>=0)this.fault('rollback','Xe đang trôi lùi','Lực kéo chưa thắng được trọng lực trên dốc. Giữ phanh, chọn số 1, thêm ga và nhả côn đến điểm bắt trước khi nhả phanh.');
 if(this.running&&this.gear>1&&this.rpm<1000&&this.gas>.5&&engage>.8)this.fault('lug','Động cơ đang bị ì','Số hiện tại quá cao với tốc độ và độ dốc. Đạp côn, về số thấp hơn rồi phối hợp ga và côn.');
 if(this.grade<-.03&&Math.abs(this.v)>5&&(this.gear===0||this.clutch>.9))this.fault('coast','Đang thả trôi xuống dốc','Về N hoặc giữ côn làm mất phanh động cơ. Chọn số thấp phù hợp, nhả côn và dùng phanh để giữ tốc độ.');
 if(this.x>=this.length){this.x=this.length;this.finished=true;this.v=0;}
 }
}
